class FoodScreen extends StatefulWidget{const FoodScreen({super.key});@override State<FoodScreen> createState()=>_FoodScreenState();}
class _FoodScreenState extends State<FoodScreen>{final ai=AiFoodService();final picker=ImagePicker();List<Meal> meals=[];List<WeightEntry> weights=[];Map<String,double>? goals;bool loading=true;String get today=>DateFormat('yyyy-MM-dd').format(DateTime.now());
 @override void initState(){super.initState();_load();}
 Future<void> _load()async{final raw=await StorageService.read('meals');final rw=await StorageService.read('body_weights');final prefs=await SharedPreferences.getInstance();final encoded=prefs.getString('nutrition_goals');meals=raw.map(Meal.fromJson).toList();weights=rw.map(WeightEntry.fromJson).toList()..sort((a,b)=>a.date.compareTo(b.date));if(encoded!=null){final p=encoded.split('|');if(p.length==4)goals={'calories':double.tryParse(p[0])??0,'protein':double.tryParse(p[1])??0,'carbs':double.tryParse(p[2])??0,'fat':double.tryParse(p[3])??0};}if(mounted)setState(()=>loading=false);if(goals==null&&mounted)WidgetsBinding.instance.addPostFrameCallback((_)=>_setup());}
 Future<void> _saveMeals()=>StorageService.write('meals',meals.map((m)=>m.toJson()).toList());Future<void> _saveWeights()=>StorageService.write('body_weights',weights.map((w)=>w.toJson()).toList());
 Future<void> _setup()async{final age=TextEditingController(),weight=TextEditingController(),height=TextEditingController();String sex='Masculino',activity='Moderado',objective='Manter peso';final ok=await showDialog<bool>(context:context,barrierDismissible:false,builder:(c)=>StatefulBuilder(builder:(c,ss)=>AlertDialog(title:const Text('Configure sua alimentação'),content:SingleChildScrollView(child:Column(children:[const Text('Estimaremos suas metas diárias de calorias e macronutrientes.'),TextField(controller:age,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Idade')),TextField(controller:weight,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'Peso inicial (kg)')),TextField(controller:height,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'Altura (cm)')),DropdownButtonFormField<String>(initialValue:sex,items:const[DropdownMenuItem(value:'Masculino',child:Text('Masculino')),DropdownMenuItem(value:'Feminino',child:Text('Feminino'))],onChanged:(v){if(v!=null)ss(()=>sex=v);},decoration:const InputDecoration(labelText:'Sexo')),DropdownButtonFormField<String>(initialValue:activity,items:const[DropdownMenuItem(value:'Sedentário',child:Text('Sedentário')),DropdownMenuItem(value:'Levemente ativo',child:Text('Levemente ativo')),DropdownMenuItem(value:'Moderado',child:Text('Moderado')),DropdownMenuItem(value:'Muito ativo',child:Text('Muito ativo')),DropdownMenuItem(value:'Extremamente ativo',child:Text('Extremamente ativo'))],onChanged:(v){if(v!=null)ss(()=>activity=v);},decoration:const InputDecoration(labelText:'Atividade')),DropdownButtonFormField<String>(initialValue:objective,items:const[DropdownMenuItem(value:'Perder peso',child:Text('Perder peso')),DropdownMenuItem(value:'Manter peso',child:Text('Manter peso')),DropdownMenuItem(value:'Ganhar peso',child:Text('Ganhar peso'))],onChanged:(v){if(v!=null)ss(()=>objective=v);},decoration:const InputDecoration(labelText:'Objetivo')),const SizedBox(height:10),const Text('Estimativas; não substituem nutricionista ou médico.',style:TextStyle(fontSize:12))])),actions:[FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('Calcular'))])));if(ok!=true)return;final a=double.tryParse(age.text.replaceAll(',','.')),w=double.tryParse(weight.text.replaceAll(',','.')),h=double.tryParse(height.text.replaceAll(',','.'));if(a==null||w==null||h==null||a<=0||w<=0||h<=0){_error('Preencha os dados corretamente.');return;}const factors={'Sedentário':1.2,'Levemente ativo':1.375,'Moderado':1.55,'Muito ativo':1.725,'Extremamente ativo':1.9};final bmr=sex=='Masculino'?10*w+6.25*h-5*a+5:10*w+6.25*h-5*a-161;final kcal=bmr*factors[activity]!+(objective=='Perder peso'?-400:objective=='Ganhar peso'?300:0);goals={'calories':kcal,'protein':w*2,'fat':kcal*.27/9};goals!['carbs']=(kcal-goals!['protein']!*4-goals!['fat']!*9)/4;final prefs=await SharedPreferences.getInstance();await prefs.setString('nutrition_goals','${goals!['calories']}|${goals!['protein']}|${goals!['carbs']}|${goals!['fat']}');if(weights.every((x)=>x.date!=today)){weights.add(WeightEntry(date:today,weight:w));await _saveWeights();}if(mounted)setState((){});}
 Future<void> _weightDialog()async{final c=TextEditingController(text:weights.where((x)=>x.date==today).isNotEmpty?weights.firstWhere((x)=>x.date==today).weight.toString():'');final ok=await showDialog<bool>(context:context,builder:(x)=>AlertDialog(title:const Text('Peso de hoje'),content:TextField(controller:c,autofocus:true,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'Peso corporal',suffixText:'kg',prefixIcon:Icon(Icons.monitor_weight_outlined))),actions:[TextButton(onPressed:()=>Navigator.pop(x),child:const Text('Cancelar')),FilledButton(onPressed:()=>Navigator.pop(x,true),child:const Text('Salvar'))]));final v=double.tryParse(c.text.replaceAll(',','.'));if(ok!=true||v==null||v<=0)return;weights.removeWhere((x)=>x.date==today);weights.add(WeightEntry(date:today,weight:v));weights.sort((a,b)=>a.date.compareTo(b.date));await _saveWeights();if(mounted)setState((){});}
 Future<void> _manual()async{final n=TextEditingController(),q=TextEditingController(),k=TextEditingController(),p=TextEditingController(),c=TextEditingController(),f=TextEditingController();final ok=await showDialog<bool>(context:context,builder:(x)=>AlertDialog(title:const Text('Adicionar refeição'),content:SingleChildScrollView(child:Column(children:[TextField(controller:n,decoration:const InputDecoration(labelText:'Alimento')),TextField(controller:q,decoration:const InputDecoration(labelText:'Quantidade')),TextField(controller:k,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'Calorias')),TextField(controller:p,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'Proteína (g)')),TextField(controller:c,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'Carboidratos (g)')),TextField(controller:f,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'Gorduras (g)'))])),actions:[TextButton(onPressed:()=>Navigator.pop(x),child:const Text('Cancelar')),FilledButton(onPressed:()=>Navigator.pop(x,true),child:const Text('Adicionar'))]));if(ok==true&&n.text.trim().isNotEmpty){meals.add(Meal(id:DateTime.now().microsecondsSinceEpoch.toString(),date:today,type:'Refeição',food:q.text.trim().isEmpty?n.text.trim():'${n.text.trim()} (${q.text.trim()})',calories:double.tryParse(k.text.replaceAll(',','.'))??0,protein:double.tryParse(p.text.replaceAll(',','.'))??0,carbs:double.tryParse(c.text.replaceAll(',','.'))??0,fat:double.tryParse(f.text.replaceAll(',','.'))??0));await _saveMeals();if(mounted)setState((){});}}
 Future<void> _aiText()async{final t=TextEditingController();final ok=await showDialog<bool>(context:context,builder:(c)=>AlertDialog(title:const Text('Analisar por texto'),content:TextField(controller:t,maxLines:4,decoration:const InputDecoration(labelText:'O que você comeu?',hintText:'Ex.: 100g de batata, 150g frango e 100g arroz',prefixIcon:Icon(Icons.auto_awesome))),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('Cancelar')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('Analisar'))]));if(ok!=true||t.text.trim().isEmpty)return;try{final r=await ai.estimateText(t.text);if(mounted)_showResult(r);}catch(e){_error(e.toString());}}
 Future<void> _camera()async{final photo=await picker.pickImage(source:ImageSource.camera,imageQuality:80);if(photo==null)return;try{final r=await ai.estimateImage(photo.path);if(mounted)_showResult(r);}catch(e){_error(e.toString());}}
 void _error(String s)=>ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(s)));
 Future<void> _showResult(FoodResult r)async{final add=await showDialog<bool>(context:context,builder:(c)=>AlertDialog(title:const Text('Estimativa nutricional'),content:SingleChildScrollView(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[...r.items.map((i)=>ListTile(contentPadding:EdgeInsets.zero,title:Text(i.name),subtitle:Text('${i.grams.toStringAsFixed(0)}g • ${i.calories.toStringAsFixed(0)} kcal • P ${i.protein.toStringAsFixed(1)}g • C ${i.carbs.toStringAsFixed(1)}g • G ${i.fat.toStringAsFixed(1)}g')),const Divider(),Text('${r.calories.toStringAsFixed(0)} kcal • P ${r.protein.toStringAsFixed(1)}g • C ${r.carbs.toStringAsFixed(1)}g • G ${r.fat.toStringAsFixed(1)}g'),const SizedBox(height:8),Text(r.note,style:Theme.of(c).textTheme.bodySmall)])),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('NÃO CONTAR')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('CONTAR'))]));if(add==true){meals.add(Meal(id:DateTime.now().microsecondsSinceEpoch.toString(),date:today,type:'Refeição',food:r.items.map((i)=>i.name).join(', '),calories:r.calories,protein:r.protein,carbs:r.carbs,fat:r.fat,source:'ai'));await _saveMeals();if(mounted)setState((){});}}
 @override Widget build(BuildContext context){if(loading)return const Center(child:CircularProgressIndicator());final tm=meals.where((m)=>m.date==today).toList();final kcal=tm.fold(0.0,(s,m)=>s+m.calories),protein=tm.fold(0.0,(s,m)=>s+m.protein),carbs=tm.fold(0.0,(s,m)=>s+m.carbs),fat=tm.fold(0.0,(s,m)=>s+m.fat);final current=weights.isEmpty?null:weights.last;return SafeArea(child:ListView(padding:const EdgeInsets.fromLTRB(16,12,16,28),children:[Row(children:[Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Alimentação',style:Theme.of(context).textTheme.headlineMedium?.copyWith(fontWeight:FontWeight.bold)),Text('Hoje • ${tm.length} registro(s)')])) ,PopupMenuButton<String>(onSelected:(v){if(v=='text')_aiText();if(v=='camera')_camera();if(v=='goals')_setup();},itemBuilder:(_)=>const[PopupMenuItem(value:'text',child:Text('🤖 Analisar por texto')),PopupMenuItem(value:'camera',child:Text('📷 Analisar por foto')),PopupMenuItem(value:'goals',child:Text('⚙️ Metas'))])]),const SizedBox(height:14),if(goals!=null)AppCard(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Meta diária',style:Theme.of(context).textTheme.titleLarge?.copyWith(fontWeight:FontWeight.bold)),const SizedBox(height:10),_bar('Calorias',kcal,goals!['calories']!,'kcal'),_bar('Proteína',protein,goals!['protein']!,'g'),_bar('Carboidratos',carbs,goals!['carbs']!,'g'),_bar('Gorduras',fat,goals!['fat']!,'g')])),Row(children:[Expanded(child:AppCard(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Icon(Icons.local_fire_department_outlined),const SizedBox(height:5),Text('${kcal.toStringAsFixed(0)}',style:Theme.of(context).textTheme.headlineSmall?.copyWith(fontWeight:FontWeight.bold)),const Text('kcal hoje')]))),const SizedBox(width:10),Expanded(child:AppCard(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Icon(Icons.fitness_center),const SizedBox(height:5),Text('${protein.toStringAsFixed(0)}g',style:Theme.of(context).textTheme.headlineSmall?.copyWith(fontWeight:FontWeight.bold)),const Text('proteína')])))]),AppCard(child:Row(children:[CircleAvatar(radius:24,child:const Icon(Icons.monitor_weight_outlined)),const SizedBox(width:12),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('Peso corporal'),Text(current==null?'—':'${current.weight.toStringAsFixed(1)} kg',style:Theme.of(context).textTheme.titleLarge?.copyWith(fontWeight:FontWeight.bold)),const Text('Registre seu peso diariamente')])),OutlinedButton(onPressed:_weightDialog,child:const Text('Registrar'))])),if(weights.length>=2)AppCard(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Evolução do peso',style:Theme.of(context).textTheme.titleLarge?.copyWith(fontWeight:FontWeight.bold)),const SizedBox(height:12),SizedBox(height:180,child:CustomPaint(painter:WeightChartPainter(weights,Theme.of(context).colorScheme.primary),child:const SizedBox.expand())),const SizedBox(height:8),Text('${DateFormat('dd/MM').format(DateTime.parse(weights.first.date))} → ${DateFormat('dd/MM').format(DateTime.parse(weights.last.date))} • ${weights.last.weight>=weights.first.weight?'+':'-'}${(weights.last.weight-weights.first.weight).abs().toStringAsFixed(1)} kg',style:Theme.of(context).textTheme.bodySmall)])),const SizedBox(height:4),Row(children:[Expanded(child:FilledButton.icon(onPressed:_aiText,icon:const Icon(Icons.auto_awesome),label:const Text('Analisar texto'))),const SizedBox(width:10),IconButton.filled(onPressed:_camera,icon:const Icon(Icons.photo_camera_outlined),tooltip:'Analisar foto')]),const SizedBox(height:8),FilledButton.tonalIcon(onPressed:_manual,icon:const Icon(Icons.add),label:const Text('Adicionar refeição manualmente')),const SizedBox(height:12),Text('Refeições de hoje',style:Theme.of(context).textTheme.titleLarge?.copyWith(fontWeight:FontWeight.bold)),if(tm.isEmpty)const AppCard(child:Text('Ainda não há refeições registradas hoje.')),...tm.map((m)=>AppCard(child:ListTile(contentPadding:EdgeInsets.zero,title:Text(m.food),subtitle:Text('${m.calories.toStringAsFixed(0)} kcal • P ${m.protein.toStringAsFixed(1)}g • C ${m.carbs.toStringAsFixed(1)}g • G ${m.fat.toStringAsFixed(1)}g'),trailing:IconButton(icon:const Icon(Icons.delete_outline),onPressed:()async{meals.remove(m);await _saveMeals();if(mounted)setState((){});}))) ]));}
 Widget _bar(String n,double v,double g,String u){final pct=g<=0?0.0:(v/g).clamp(0.0,1.0).toDouble();return Padding(padding:const EdgeInsets.symmetric(vertical:5),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(children:[Expanded(child:Text(n)),Text('${v.toStringAsFixed(0)} / ${g.toStringAsFixed(0)} $u')]),const SizedBox(height:4),ClipRRect(borderRadius:BorderRadius.circular(8),child:LinearProgressIndicator(value:pct,minHeight:8))]));}
}
class WeightChartPainter extends CustomPainter{final List<WeightEntry> data;final Color color;WeightChartPainter(this.data,this.color);@override void paint(Canvas canvas,Size size){if(data.length<2)return;final minW=data.map((e)=>e.weight).reduce((a,b)=>a<b?a:b);final maxW=data.map((e)=>e.weight).reduce((a,b)=>a>b?a:b);final range=(maxW-minW).abs()<0.1?1:(maxW-minW);final path=Path();for(int i=0;i<data.length;i++){final x=i*(size.width/(data.length-1));final y=size.height-((data[i].weight-minW)/range)*(size.height-24)-8;if(i==0)path.moveTo(x,y);else path.lineTo(x,y);}final p=Paint()..color=color..style=PaintingStyle.stroke..strokeWidth=3..strokeCap=StrokeCap.round;canvas.drawPath(path,p);final dot=Paint()..color=color;for(int i=0;i<data.length;i++){final x=i*(size.width/(data.length-1));final y=size.height-((data[i].weight-minW)/range)*(size.height-24)-8;canvas.drawCircle(Offset(x,y),4,dot);}}@override bool shouldRepaint(covariant WeightChartPainter old)=>old.data!=data||old.color!=color;}
